private fun loadFromStorage() {
    viewModelScope.launch {
        withContext(Dispatchers.IO) {
            // Try Room DB first, fall back to JSON
            val roomState = try { loadFromRoom() } catch (_: Exception) { null }
            val saved = storage.load()

            val savedKids = if (roomState != null) roomState.first else saved.kids.map { it.toKid() }
            val savedAppointments = if (roomState != null) roomState.second else saved.appointments.map { it.toAppointment() }
            val savedMeals = if (roomState != null) roomState.third else saved.meals.mapValues { (_, list) -> list.map { it.toMealItem() } }
            val savedStreaks = if (roomState != null) roomState.fourth else saved.streaks.mapValues { (_, v) -> v.toStreakInfo() }

private suspend fun loadFromRoom(): Quadruple<List<Kid>, List<Appointment>, Map<String, List<MealItem>>, Map<String, StreakInfo>>? {
    val parent = db.parentDao().get() ?: return null
    val entities = db.kidDao().getAll()
    if (entities.isEmpty()) return null

    val json = kotlinx.serialization.json.Json { prettyPrint = false; ignoreUnknownKeys = true }
    val kids = entities.map { e ->
        val growth: List<GrowthPoint> = if (e.growthJson.isNotBlank()) {
            try {
                json.decodeFromString(
                    kotlinx.serialization.builtins.ListSerializer(SerializableGrowthPoint.serializer()),
                    e.growthJson
                ).map { GrowthPoint(it.label, it.height, it.weight) }
            } catch (_: Exception) { emptyList() }
        } else emptyList()
        Kid(
            id = e.id, name = e.name, age = e.age, gender = e.gender,
            school = e.school, grade = e.grade, heightCm = e.heightCm,
            weightKg = e.weightKg, avatarColor = e.avatarColor,
            overallScore = e.overallScore, growth = growth,
            dental = try { HealthFlag.valueOf(e.dental) } catch (_: Exception) { HealthFlag.GOOD },
            eyesight = try { HealthFlag.valueOf(e.eyesight) } catch (_: Exception) { HealthFlag.GOOD },
            nutrition = try { HealthFlag.valueOf(e.nutrition) } catch (_: Exception) { HealthFlag.GOOD },
            lastCheckup = e.lastCheckup
        )
    }
    val appointments = db.appointmentDao().getAll().map { e ->
        Appointment(e.id, e.doctorName, e.specialty, e.kidName, e.date, e.time)
    }
    val mealEntities = db.mealDao().getAll()
    val meals: Map<String, List<MealItem>> = mealEntities.groupBy { it.kidId }.mapValues { (_, list) ->
        list.map { MealItem(it.id, it.timeSlot, it.name, it.detail, it.kcal, it.eaten) }
    }
    val streaks = db.streakDao().getAll().associate { e ->
        e.kidId to StreakInfo(e.currentStreak, e.bestStreak, e.lastLogDate)
    }
    return Quadruple(kids, appointments, meals, streaks)
}

private data class Quadruple<A, B, C, D>(val first: A, val second: B, val third: C, val fourth: D)

