private suspend fun loadFromRoom(): Quadruple<List<Kid>, List<Appointment>, Map<String, List<MealItem>>, Map<String, StreakInfo>>? {
    val parent = db.parentDao().profile() ?: return null
    if (!parent.isLoggedIn) return null
    val entities = db.kidDao().allKids()
    // allKids() returns Flow, we need first value
    var kidsList: List<KidEntity> = emptyList()
    kotlinx.coroutines.flow.firstOrNull(entities)?.let { kidsList = it }
    if (kidsList.isEmpty()) return null

    val json = kotlinx.serialization.json.Json { prettyPrint = false; ignoreUnknownKeys = true }
    val kids = kidsList.map { e: KidEntity ->
        val growth: List<GrowthPoint> = if (e.growthJson.isNotBlank()) {
            try {
                json.decodeFromString(
                    kotlinx.serialization.builtins.ListSerializer(SerializableGrowthPoint.serializer()),
                    e.growthJson
                ).map { g -> GrowthPoint(g.label, g.height, g.weight) }
            } catch (_: Exception) { emptyList() }
        } else emptyList()
        Kid(
            id = e.id, name = e.name, age = e.age, gender = e.gender,
            school = e.school, grade = e.grade, heightCm = e.heightCm,
            weightKg = e.weightKg, avatarColor = e.avatarColor,
            overallScore = e.overallScore, growth = growth,
            dental = try { HealthFlag.valueOf(e.dental) } catch (_: Exception) { HealthFlag.GOOD },
            eyesight = try { HealthFlag.valueOf(e.eyesight) } catch (_: Exception) { HealthFlag.GOOD },
            nutrition = try { HealthFlag.valueOf(e.nutrition) } catch (_: Exception) { HealthFlag.GOOD },
            lastCheckup = e.lastCheckup
        )
    }
    val appointmentEntities = db.appointmentDao().allAppointmentsOnce()
    val appointments = appointmentEntities.map { e: AppointmentEntity ->
        Appointment(e.id, e.doctorName, e.specialty, e.kidName, e.date, e.time)
    }
    val allMeals = mutableListOf<MealItemEntity>()
    kidsList.forEach { k: KidEntity ->
        allMeals.addAll(db.mealDao().mealsForKidOnce(k.id))
    }
    val meals: Map<String, List<MealItem>> = allMeals.groupBy { m: MealItemEntity -> m.kidId }.mapValues { (_, list) ->
        list.map { m -> MealItem(m.id, m.timeSlot, m.name, m.detail, m.kcal, m.eaten) }
    }
    val streaks = mutableMapOf<String, StreakInfo>()
    kidsList.forEach { k: KidEntity ->
        val se: StreakEntity? = db.streakDao().streakForKidOnce(k.id)
        if (se != null) streaks[k.id] = StreakInfo(se.currentStreak, se.bestStreak, se.lastLogDate)
    }
    return Quadruple(kids, appointments, meals, streaks)
}

